import{G as e,W as t,n,rt as r}from"./chunks/framework.CJ3GlOSn.js";var i=JSON.parse(`{"title":"Xlang","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/xlang.md","filePath":"03-developer/models/xlang.md"}`),a={name:`03-developer/models/xlang.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="xlang" tabindex="-1">Xlang <a class="header-anchor" href="#xlang" aria-label="Permalink to “Xlang”">​</a></h1><p>The <code>Xlang</code> model is used to manage site languages and multilingual support. Languages are distinguished by URL prefixes; for example, the site&#39;s root path is used for the default language, while paths such as <code>/de</code> and <code>/fa</code> are used for other languages.</p><p>The name <code>Xlang</code> was chosen to avoid naming conflicts with Laravel&#39;s language system and packages related to <code>Lang</code>.</p><h2 id="data-structure" tabindex="-1">Data structure <a class="header-anchor" href="#data-structure" aria-label="Permalink to “Data structure”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Unique language ID</td></tr><tr><td><code>name</code></td><td>VARCHAR(255)</td><td>No</td><td>Language name</td></tr><tr><td><code>tag</code></td><td>VARCHAR(7), unique</td><td>No</td><td>Language code and URL prefix, such as <code>fa</code> or <code>de</code></td></tr><tr><td><code>rtl</code></td><td>TINYINT(1)</td><td>No</td><td>Indicates whether the language is right-to-left; defaults to <code>0</code></td></tr><tr><td><code>is_default</code></td><td>TINYINT(1)</td><td>No</td><td>Indicates whether this is the site&#39;s default language; defaults to <code>0</code></td></tr><tr><td><code>img</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Language flag image filename</td></tr><tr><td><code>emoji</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Language flag emoji</td></tr><tr><td><code>sort</code></td><td>TINYINT</td><td>No</td><td>Language display order; defaults to <code>0</code></td></tr><tr><td><code>deleted_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Language soft deletion time</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Record creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Record last update time</td></tr></tbody></table><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="imgurl" tabindex="-1"><code>imgUrl()</code> <a class="header-anchor" href="#imgurl" aria-label="Permalink to “imgUrl()”">​</a></h3><p>Returns the optimized language flag image URL; if no image is available, the site logo is used as a fallback.</p><h3 id="imgoriginalurl" tabindex="-1"><code>imgOriginalUrl()</code> <a class="header-anchor" href="#imgoriginalurl" aria-label="Permalink to “imgOriginalUrl()”">​</a></h3><p>Returns the original language flag image URL; if no image is available, the site logo is used as a fallback.</p><h3 id="getroutekeyname" tabindex="-1"><code>getRouteKeyName()</code> <a class="header-anchor" href="#getroutekeyname" aria-label="Permalink to “getRouteKeyName()”">​</a></h3><p>Uses the <code>tag</code> field instead of <code>id</code> for Route Model Binding.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>The <code>tag</code> field has a unique index, so each language must have a unique code.</li><li>The language prefix is applied to site routes, and pages, including posts and categories, follow the multilingual structure.</li><li>The site&#39;s default language is specified through <code>is_default</code>. Ensuring that only one language is set as the default must be handled in the application logic; the table structure alone does not enforce it.</li><li>The <code>rtl</code> field is used to identify right-to-left languages, such as Persian and Arabic.</li><li>The <code>sort</code> field specifies the display order of languages.</li><li>Language files are created as JSON files in the <code>resources/lang</code> directory. For example, <code>ar.json</code>, <code>de.json</code>, <code>fa.json</code>, and <code>fr.json</code> are located in this directory.</li><li>English is the primary content language, and no separate translation file is provided for it. Administrators can manage existing language files through the editor.</li><li>Flag files are available in the <code>langz/</code> directory, and their optimized versions are available in the <code>langz/optimized-</code> directory.</li><li>The <code>deleted_at</code> field is intended to record the soft deletion time; whether Soft Deletes are enabled depends on the model configuration.</li></ul>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};